INSERT INTO bands(id,name,country,bio,source)
SELECT 'possessed','Possessed','United States','A raw guitar attack and a darker rhythmic weight. Possessed brings death and thrash into the same conversation through Seven Churches. Start with The Exorcist, follow the changes in pressure, then hear the record beside Slayer and Venom.','https://music.apple.com/us/album/seven-churches/980777677' WHERE EXISTS (SELECT 1 FROM albums) ON CONFLICT(id) DO NOTHING;
INSERT INTO albums(id,band_id,title,year,genre,note,description,source,artwork,credit,tracks,status)
SELECT 'seven-churches','possessed','Seven Churches',1985,'Death / Thrash','A raw attack. The edge between speed and darkness.','Seven Churches brings a raw death/thrash edge to the opening selection. Follow the guitar phrases through The Exorcist, then the shift in pressure as the record unfolds. Set beside Slayer and Venom, it offers another way into the darker end of the archive.','https://music.apple.com/us/album/seven-churches/980777677','/assets/albums/seven-churches.jpg','Possessed / respective album artwork rights holders.','["The Exorcist","Pentagram","Burning In Hell","Evil Warriors","Seven Churches","Satan''s Curse","Holy Hell","Twisted Minds","Fallen Angel","Death Metal"]'::jsonb,'published' WHERE EXISTS (SELECT 1 FROM albums) ON CONFLICT(id) DO NOTHING;
UPDATE albums SET status='draft',updated_at=now() WHERE id IN ('exorkizein','once','paranoid');
UPDATE stories SET status='draft',updated_at=now() WHERE id='weight-of-the-riff';
INSERT INTO stories(id,kind,title,deck,author,body,album_ids,status,published_at)
SELECT 'seven-churches','review','At the edge of the abyss.','Possessed’s Seven Churches, and the tension between speed and weight.','RIFF CULT Editorial','["Seven Churches makes a useful third voice beside Slayer and Venom. Listen first for the shape of a guitar phrase, then for the weight of the rhythm underneath it. The rough surface is only one part of the picture.","The Exorcist opens a route into the record. Let one listen follow the guitar and another follow the drums. A change in emphasis can reveal a different sense of momentum without changing the music itself.","The title track provides another point of entry. Hear it in sequence, then return to the opening track and notice which details have become easier to follow. Whole records reward that kind of return visit.","Keep Seven Churches in conversation with the other two records in the opening selection. Their different attacks give the same listening session room to move: a sharp turn, a coarse edge, another shade of darkness."]'::jsonb,'["seven-churches"]'::jsonb,'published','2026-10-22T12:00:00Z'::timestamptz WHERE EXISTS (SELECT 1 FROM albums) ON CONFLICT(id) DO NOTHING;
UPDATE stories SET deck='Slayer. Venom. Possessed. Three records, three different shades of darkness.',body='["Darkness in metal is not one sound. It can live in a tightly wound riff, a ragged guitar attack or a dense arrangement that seems to close in around the listener. These three records make a route through those different kinds of pressure.","Start with Slayer’s Reign in Blood. Follow the sharp turns between phrases and notice how the rhythm section keeps the attack together. Return to Raining Blood at the end of the sequence and listen for the change in weight before the band drives forward again.","Move to Venom’s Black Metal for a different edge. Follow the rhythm underneath the rough guitar sound, then hear how the vocal attack changes the shape of a phrase. Placed after Slayer, the contrast is as useful as the shared sense of menace.","Finish with Possessed’s Seven Churches. Its raw death/thrash attack brings another texture into the selection. Follow the changes in pressure between the guitar phrases, then listen to how the rhythm section carries the sequence toward Death Metal.","Keep the three together as a listening sequence rather than a ranking. Slayer, Venom and Possessed offer different ways to build intensity; the changes between them are part of the point."]'::jsonb,album_ids='["reign-in-blood","black-metal","seven-churches"]'::jsonb,updated_at=now() WHERE id='after-dark';
UPDATE placements SET album_ids='["reign-in-blood","black-metal","seven-churches"]'::jsonb WHERE id='hero';
UPDATE placements SET album_ids='["agent-orange","coma-of-souls","kill","seven-churches","reign-in-blood","black-metal","pleasure-to-kill","powerslave"]'::jsonb WHERE id='rotation';
